<?php require __DIR__.'/includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();foreach($_POST['qty']??[] as $id=>$q){$id=(int)$id;$q=(int)$q;if($q<1)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min(20,$q);}if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);notice('Your bag has been updated.');go('cart.php');}$a=items($pdo);$sum=total_items($a);$pageTitle='Your bag';require __DIR__.'/includes/header.php';?>
